public List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph graph) {
  // create an empty list to store the result
  List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

  // iterate over all the edges in the graph
  for (E edge : graph.getEdges()) {
    // compute the list of minimal separators for the edge
    List<Pair<Integer, Integer>> minimalSeparators = getMinimalSeparators(edge);

    // add the minimal separators to the global separator list
    globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
  }

  return globalSeparatorList;
}

/**
 * Computes the list of minimal separators for a given edge {@code edge}. Note: the result may contain duplicates
 * @return the list of minimal separators for the edge
 */
private List<Pair<Integer, Integer>> getMinimalSeparators(E edge) {
  // create an empty list to store the result
  List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

  // get the vertices connected to the edge
  List<Integer> vertices = edge.getVertices();

  // get the distance matrix of the graph
  Matrix<E> distanceMatrix = graph.getDistanceMatrix();

  // compute the shortest path between the vertices
  int shortestPath = distanceMatrix.getShortestPath(vertices.get(0), vertices.get(1));

  // iterate over all the possible pairs of vertices
  for (int i = 0; i < vertices.size() - 1; i++) {
    for (int j = i + 1; j < vertices.size(); j++) {
      int distance = distanceMatrix.getDistance(vertices.get(i), vertices.get(j));

      // if the distance is equal to the shortest path, then the pair i and j is a minimal separator
      if (distance == shortestPath) {
        minimalSeparators.add(new Pair<>(vertices.get(i), vertices.get(j)));
      }
    }
  }

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer, Integer>> separators = new ArrayList<>();
        for (V vertex : graph.getNeighbors(edge.getDestination())) {
            for (E neighborEdge : graph.getNeighbors(vertex)) {
                // Check if the edge is not the edge being inspected
                if (neighborEdge != edge) {
                    continue;
                }
                List<Pair<Integer, Integer>> neighborSeparators = new ArrayList<>();
                for (V neighborVertex : graph.getNeighbors(neighborEdge.getDestination())) {
                    if (neighborVertex != vertex) {
                        neighborSeparators.add(new Pair<>(neighborVertex.getId(), vertex.getId()));
                    }
                }
                separators.addAll(neighborSeparators);
            }
        }
        globalSeparatorList.add(new Pair<>(separators, edge));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
  List<Pair<List<Pair<Integer, Integer>>, E>> result = new ArrayList<>();
  for (E edge : graph.getEdges()) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (Pair<Integer, Integer> neighbor : graph.getNeighbors(edge.getFirst())) {
      if (neighbor.getFirst() == edge.getSecond()) {
        separators.add(new Pair<>(neighbor.getFirst(), neighbor.getSecond()));
      }
    }
    result.add(new Pair<>(separators, edge));
  }
  return result;
}

