public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (!line.isEmpty()) {
                String[] tokens = line.split(",");
                if (tokens.length == 4) {
                    long startTime = Long.parseLong(tokens[0].trim());
                    long endTime = Long.parseLong(tokens[1].trim());
                    int threadId = Integer.parseInt(tokens[2].trim());
                    String threadName = tokens[3].trim();
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (range.isWithinTimeRange(startTime, endTime)) {
                            threadSnapshots.add(new ThreadSnapshot(startTime, endTime, threadId, threadName));
                        }
                    }
                } else {
                    System.out.println("Invalid format for line: " + line);
                }
            }
        }
    }
    return threadSnapshots;
}
